#include<stdio.h>
#include<stdlib.h>
main()
{
	int a,b,c;
	printf("请输入需要对方猜测的数字");
	scanf("%d",&a);
	system("cls");
	int i=1;
	while(i)
	{
		printf("请输入你猜测的数字：");
		scanf("%d",&b);
		i=b-a;
		if(i==0)	break;
		if(i>0)
			switch(i/10)
				{
					case 0:
						printf("大了几个数（10以内）");
						break;
					case 1:
						printf("大了十几个数（10-20个数）");
						break;
					default:
						printf("大了很多（20以外）");
						break;
				}
		else	{	//i=-i;
					switch(-i/10)
						{
							case 0:
							printf("小了几个数（10以内）");
							break;
						case 1:
							printf("小了十几个数（10-20个数）");
							break;
						default:
							printf("小了很多（20以外）");
							break;
					}
				}

	}
	printf("恭喜你猜对了答案是%d\n",a);
}

